// Fetch this week's activity for the configured repo and build the Claude prompt.
// Secrets come from env vars (set them on your n8n instance): GITHUB_TOKEN.
const cfg = $input.first().json;
const owner = cfg.owner;
const repo = cfg.repo;
const language = (cfg.language || 'en').toLowerCase();
const token = $env.GITHUB_TOKEN;
const sinceIso = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
const sinceTs = new Date(sinceIso).getTime();

const helpers = this.helpers;
async function gh(path) {
  return helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com${path}`,
    headers: {
      'User-Agent': 'n8n-weekly-summary',
      'Accept': 'application/vnd.github+json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    json: true,
  });
}

const commits = await gh(`/repos/${owner}/${repo}/commits?since=${sinceIso}&per_page=100`);
const issuesRaw = await gh(`/repos/${owner}/${repo}/issues?state=closed&since=${sinceIso}&per_page=100`);
const pullsRaw = await gh(`/repos/${owner}/${repo}/pulls?state=closed&per_page=100&sort=updated&direction=desc`);

const closedIssues = (issuesRaw || []).filter((i) => !i.pull_request);
const mergedPRs = (pullsRaw || []).filter((p) => p.merged_at && new Date(p.merged_at).getTime() >= sinceTs);

const lines = [];
lines.push(`Repository: ${owner}/${repo}`);
lines.push(`Window: last 7 days (since ${sinceIso})`);
lines.push('');
lines.push(`Commits (${commits.length}):`);
lines.push(...commits.slice(0, 40).map((c) => `- ${String(c.commit.message).split('\n')[0]}`));
lines.push('');
lines.push(`Merged PRs (${mergedPRs.length}):`);
lines.push(...mergedPRs.slice(0, 40).map((p) => `- #${p.number} ${p.title}`));
lines.push('');
lines.push(`Closed issues (${closedIssues.length}):`);
lines.push(...closedIssues.slice(0, 40).map((i) => `- #${i.number} ${i.title}`));
const dataBlock = lines.join('\n');

const langLine = language === 'fr' ? 'Write the summary in French.' : 'Write the summary in English.';
const prompt = `You are a developer-relations writer. Using the raw GitHub activity below, write a concise, upbeat weekly summary of this repository: 2-3 short paragraphs on the themes and impact, then a short bulleted "Highlights" list. Do not just restate the raw list. ${langLine}\n\n${dataBlock}`;

return [{ json: { owner, repo, language, since: sinceIso, counts: { commits: commits.length, mergedPRs: mergedPRs.length, closedIssues: closedIssues.length }, prompt } }];
